import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

const testimonials = [
  {
    name: 'Rajesh Meena',
    age: 52,
    role: 'Paralysis Recovery',
    branch: 'Udaipur Branch',
    text: "After 2 years of paralysis, Dr. Piyush's team got me walking in 4 months. I came in on a stretcher and walked out on my own two feet.",
    initials: 'R',
    rating: 5,
  },
  {
    name: 'Neha Joshi',
    age: 38,
    role: 'Back Pain Relief',
    branch: 'Udaipur Branch',
    text: "Eight years of chronic back pain resolved in 6 weeks. The IFT and spinal traction combination worked when everything else had failed me.",
    initials: 'N',
    rating: 5,
  },
  {
    name: 'Amit Rathore',
    age: 24,
    role: 'Sports Injury',
    branch: 'Ahmedabad Branch',
    text: "As a national-level athlete, ACL injuries mean career end. JK Physio proved everyone wrong. Back on the field in 5 months, stronger than before.",
    initials: 'A',
    rating: 5,
  },
  {
    name: 'Sunita Patel',
    age: 61,
    role: 'Surgery Rehab',
    branch: 'Ahmedabad Branch',
    text: "Post knee replacement, I was told recovery takes a year. JK Physio's protocol had me walking confidently in 3 months.",
    initials: 'S',
    rating: 5,
  },
  {
    name: 'Deepak Verma',
    age: 35,
    role: 'Gym & Fitness',
    branch: 'Udaipur Branch',
    text: "The gym at JK Physio is world-class. Combined with Dr. Piyush's program, I lost 18 kg and regained full mobility in just 4 months.",
    initials: 'D',
    rating: 5,
  },
  {
    name: 'Yash Trivedi',
    age: 22,
    role: 'Sports Injury',
    branch: 'Udaipur Branch',
    text: "Cricket injury sidelined me. JK Physio's sports rehab was world-class. Back on the pitch in record time, better than ever before.",
    initials: 'Y',
    rating: 5,
  },
  {
    name: 'Geeta Patel',
    age: 60,
    role: 'Knee Rehabilitation',
    branch: 'Udaipur Branch',
    text: "Knee osteoarthritis at 60 felt like a death sentence. JK Physio's laser and manual therapy gave me back my full independence.",
    initials: 'G',
    rating: 5,
  },
  {
    name: 'Meena Gupta',
    age: 55,
    role: 'Shoulder Recovery',
    branch: 'Udaipur Branch',
    text: "Frozen shoulder for 18 months. Tried everything. JK Physio resolved it in 8 weeks with ultrasound and manual therapy. Unmatched.",
    initials: 'M',
    rating: 5,
  },
];

const Stars = ({ count = 5 }) => (
  <div className="flex gap-0.5">
    {Array.from({ length: count }).map((_, i) => (
      <svg key={i} className="w-4 h-4" fill="#f59e0b" viewBox="0 0 20 20">
        <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
      </svg>
    ))}
  </div>
);

const TestimonialsPage = () => {
  const navigate = useNavigate();
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    window.scrollTo(0, 0);
    setTimeout(() => setVisible(true), 100);
  }, []);

  return (
    <div className="min-h-screen" style={{ backgroundColor: '#f7f5f2' }}>

      {/* Hero Section */}
      <div className="pt-28 pb-16 px-6 max-w-6xl mx-auto">

        {/* Back button */}
        <button
          onClick={() => navigate('/')}
          className="inline-flex items-center gap-2 text-sm font-semibold mb-10 bg-white px-4 py-2 rounded-full border cursor-pointer"
          style={{ color: '#db261d', borderColor: '#fecaca' }}
        >
          <svg className="w-4 h-4" fill="none" viewBox="0 0 16 16">
            <path d="M10 4L6 8l4 4" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          Back to Home
        </button>

        {/* Split heading row */}
        <div className="flex flex-col lg:flex-row lg:items-end gap-8 lg:gap-16 mb-16">
          {/* Left */}
          <div className="flex-1">
            {/* Label */}
            <div className="flex items-center gap-3 mb-6">
              <div style={{ width: '32px', height: '2px', backgroundColor: '#db261d' }}></div>
              <span className="text-xs font-bold tracking-widest uppercase" style={{ color: '#db261d' }}>
                Patient Stories
              </span>
            </div>

            <h1
              className="font-bold text-slate-900 leading-tight"
              style={{ fontSize: 'clamp(2.5rem, 5vw, 4rem)', fontFamily: 'Georgia, serif' }}
            >
              What Our{' '}
              <em style={{ color: '#db261d', fontStyle: 'italic' }}>Patients Say</em>
            </h1>
          </div>

          {/* Right */}
          <div className="flex-1 lg:max-w-md">
            <p className="text-slate-500 leading-relaxed text-base">
              Real stories from real patients across our 4 branches — their journeys
              from pain to performance inspire everything we do.
            </p>

            {/* Stats row */}
            <div className="flex gap-8 mt-8">
              {[['500+', 'Patients Treated'], ['98%', 'Success Rate'], ['4.9★', 'Avg Rating']].map(([num, label]) => (
                <div key={label}>
                  <div className="text-xl font-bold text-slate-800">{num}</div>
                  <div className="text-xs text-slate-400 mt-0.5">{label}</div>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Testimonials Grid — 4 columns */}
        <div
          className="grid gap-5"
          style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))' }}
        >
          {testimonials.map((t, i) => (
            <div
              key={t.name}
              className={`fade-up fade-up-delay-${(i % 4) + 1} ${visible ? 'visible' : ''}`}
              style={{
                background: 'white',
                borderRadius: '16px',
                padding: '28px',
                border: '1px solid #ede9e4',
                boxShadow: '0 2px 12px rgba(0,0,0,0.04)',
                transition: 'transform 0.25s ease, box-shadow 0.25s ease',
                display: 'flex',
                flexDirection: 'column',
                gap: '16px',
              }}
              onMouseEnter={e => {
                e.currentTarget.style.transform = 'translateY(-5px)';
                e.currentTarget.style.boxShadow = '0 16px 36px rgba(219,38,29,0.09)';
              }}
              onMouseLeave={e => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = '0 2px 12px rgba(0,0,0,0.04)';
              }}
            >
              {/* Stars */}
              <Stars count={t.rating} />

              {/* Quote */}
              <p
                className="text-slate-600 leading-relaxed text-sm flex-1"
                style={{ fontStyle: 'italic' }}
              >
                "{t.text}"
              </p>

              {/* Divider */}
              <div style={{ height: '1px', backgroundColor: '#f1ede8' }} />

              {/* Author */}
              <div className="flex items-center gap-3">
                <div
                  className="flex-shrink-0 w-11 h-11 rounded-full flex items-center justify-center text-white font-bold text-sm"
                  style={{ backgroundColor: '#9b1c1c' }}
                >
                  {t.initials}
                </div>
                <div>
                  <div className="font-semibold text-slate-800 text-sm">
                    {t.name}, {t.age}
                  </div>
                  <div
                    className="text-xs font-bold uppercase tracking-wide mt-0.5"
                    style={{ color: '#db261d' }}
                  >
                    {t.role}
                  </div>
                  <div className="text-xs text-slate-400 mt-0.5">{t.branch}</div>
                </div>
              </div>
            </div>
          ))}
        </div>

        {/* CTA */}
        <div
          className="mt-16 rounded-3xl p-10 text-center"
          style={{ background: 'linear-gradient(135deg, #db261d, #b91c1c)' }}
        >
          <h3 className="text-2xl font-bold text-white mb-3">
            Ready to Write Your Success Story?
          </h3>
          <p className="text-red-100 mb-6 text-sm">
            Join hundreds of patients who have restored their movement and reclaimed their lives.
          </p>
          <button
            onClick={() => navigate('/#contact')}
            className="bg-white font-bold px-8 py-3.5 rounded-xl text-sm cursor-pointer border-none"
            style={{ color: '#db261d', boxShadow: '0 4px 14px rgba(0,0,0,0.15)' }}
          >
            Book a Consultation →
          </button>
        </div>
      </div>
    </div>
  );
};

export default TestimonialsPage;
